1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Converts a raw telephone entry into E.164 form.
5	 *
6	 * <p>Rules: strip spaces, dashes and brackets; keep a leading {@code '+'} and its country
7	 * code when present; otherwise assume country code {@code '+61'} and drop a single leading
8	 * {@code '0'} from the national digits. The result is {@code '+'} followed by 8 to 15 digits;
9	 * anything that cannot form a valid E.164 number yields {@code null}.
10	 *
11	 * <p>The conversion is idempotent — feeding an already-E.164 value back in returns it
12	 * unchanged — so it can normalize both incoming requests and already-stored values for
13	 * comparison.
14	 */
15	final class TelephoneNormalizer {
16	
17	    private TelephoneNormalizer() {
18	    }
19	
20	    /**
21	     * @param raw the raw telephone text (may be {@code null})
22	     * @return the E.164 string, or {@code null} when {@code raw} cannot form a valid one
23	     */
24	    static String toE164(String raw) {
25	        if (raw == null) {
26	            return null;
27	        }
28	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
29	        String digits;
30	        if (cleaned.startsWith("+")) {
31	            digits = cleaned.substring(1);
32	        }
33	        else {
34	            if (cleaned.startsWith("0")) {
35	                cleaned = cleaned.substring(1);
36	            }
37	            digits = "61" + cleaned;
38	        }
39	        if (!digits.matches("[0-9]{8,15}")) {
40	            return null;
41	        }
42	        return "+" + digits;
43	    }
44	}
