19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone()))) {
21	                throw new DuplicateOwnerTelephoneException(request.getTelephone());
22	            }
23	        }
24	    }
25	}
